949	+import 'dart:async';
950	+
951	+import 'package:flutter_bloc/flutter_bloc.dart';
952	+
953	+import '../../domain/entities/export_job_state.dart';
954	+import '../../domain/repositories/export_repository.dart';
955	+
956	+/// Drives `ExportStatusSheet` (spec-7-1) — a fresh, `get_it`-factory-
957	+/// scoped instance per download-icon tap (Code Map: the `registerFactory`
958	+/// one-shot-cubit precedent set by `TextEntryCubit`), closed by the call
959	+/// site itself once done with it (`MeusRegistrosScreen`'s own export handler/
960	+/// `ExportStatusSheet.show()`, mirroring `InsertionModal.show()`'s own
961	+/// cubit-disposal convention), never by a `get_it` `dispose:` hook.
962	+///
963	+/// Starts in [ExportJobState.preparing] — the same visual the
964	+/// `export-summary-create` 202 response's own `status: 'pending'` always
965	+/// implies (`openapi.yaml`), so no separate "creating..." state is needed
966	+/// before [start]'s own `createJob` call resolves.
967	+class ExportJobCubit extends Cubit<ExportJobState> {
968	+  ExportJobCubit(this._repository) : super(const ExportJobState.preparing());
969	+
970	+  final ExportRepository _repository;
971	+
972	+  /// Design Notes — fixed poll cadence (docs/input is silent on this):
973	+  /// the server job always reaches a terminal state, so no client
974	+  /// timeout exists either.
975	+  static const _pollInterval = Duration(seconds: 2);
976	+
977	+  /// Review finding (blind-hunter/edge-case-hunter layers) — a persistent
978	+  /// `getStatus` failure (as opposed to one flaky blip) would otherwise
979	+  /// poll forever with the sheet stuck on its last state and no visible
980	+  /// indication anything is wrong. After this many *consecutive* failures,
981	+  /// [_poll] gives up and surfaces the existing generic [ExportJobError]
982	+  /// state instead — reusing the sheet's own already-built error visual
983	+  /// rather than inventing a new one.
984	+  static const _maxConsecutivePollFailures = 5;
985	+
986	+  String? _jobId;
987	+  Timer? _pollTimer;
988	+  int _consecutivePollFailures = 0;
989	+
990	+  /// Review finding (blind-hunter/edge-case-hunter layers) — `Timer.
991	+  /// periodic` doesn't wait for one tick's own `_poll()` to finish before
992	+  /// firing the next; without this guard, a `getStatus` call slower than
993	+  /// [_pollInterval] could race a second, overlapping call, and a late,
994	+  /// stale response landing after a newer terminal state was already
995	+  /// emitted could "un-terminate" an already-finished job in the UI.
996	+  bool _pollInFlight = false;
997	+
998	+  /// Creates the export job for [periodStart]/[periodEnd]
999	+  /// (`export-summary-create`) and, on success, starts this cubit's own
1000	+  /// `Timer.periodic` poll loop against `export-status-get`.
1001	+  ///
1002	+  /// Returns `false` on a create failure (Boundaries: "Create fails →
1003	+  /// inline error, sheet never opens") — the same failure is also
1004	+  /// emitted as [ExportJobState.error] so the caller can read [state] for
1005	+  /// [Failure.message] without this method also having to hand back the
1006	+  /// raw `Failure` itself (the `Either<Failure, T>` shape, RNF09, is the
1007	+  /// repository's own contract, not every cubit method's).
1008	+  Future<bool> start({
1009	+    required DateTime periodStart,
1010	+    required DateTime periodEnd,
1011	+  }) async {
1012	+    final result = await _repository.createJob(
1013	+      periodStart: periodStart,
1014	+      periodEnd: periodEnd,
1015	+    );
1016	+    if (isClosed) {
1017	+      return false;
1018	+    }
1019	+    return result.match(
1020	+      (failure) {
1021	+        emit(ExportJobState.error(failure));
1022	+        return false;
1023	+      },
1024	+      (jobId) {
1025	+        _jobId = jobId;
1026	+        _startPolling();
1027	+        return true;
1028	+      },
1029	+    );
1030	+  }
1031	+
1032	+  void _startPolling() {
1033	+    _pollTimer?.cancel();
1034	+    _pollTimer = Timer.periodic(_pollInterval, (_) => _poll());
1035	+  }
1036	+
1037	+  Future<void> _poll() async {
1038	+    final jobId = _jobId;
1039	+    if (jobId == null || _pollInFlight || _isTerminal(state)) {
1040	+      return;
1041	+    }
1042	+    _pollInFlight = true;
1043	+    try {
1044	+      final result = await _repository.getStatus(jobId);
1045	+      if (isClosed || _isTerminal(state)) {
1046	+        return;
1047	+      }
1048	+      result.match(
1049	+        (failure) {
1050	+          // A transient poll failure (docs/input is silent on this) is
1051	+          // swallowed rather than surfaced, so one flaky network blip
1052	+          // never flips a still-running job to a false terminal error —
1053	+          // the next tick simply tries again. A *persistent* one gives up
1054	+          // after [_maxConsecutivePollFailures] instead of polling
1055	+          // forever.
1056	+          _consecutivePollFailures++;
1057	+          if (_consecutivePollFailures >= _maxConsecutivePollFailures) {
1058	+            _pollTimer?.cancel();
1059	+            emit(ExportJobState.error(failure));
1060	+          }
1061	+        },
1062	+        (newState) {
1063	+          _consecutivePollFailures = 0;
1064	+          emit(newState);
1065	+          if (_isTerminal(newState)) {
1066	+            _pollTimer?.cancel();
1067	+          }
1068	+        },
1069	+      );
1070	+    } finally {
1071	+      _pollInFlight = false;
1072	+    }
1073	+  }
1074	+
1075	+  bool _isTerminal(ExportJobState state) =>
1076	+      state is ExportJobDone ||
1077	+      state is ExportJobError ||
1078	+      state is ExportJobEmptyPeriod;
1079	+
1080	+  @override
1081	+  Future<void> close() {
1082	+    _pollTimer?.cancel();
1083	+    return super.close();
1084	+  }
1085	+}
